/**
 * 🔐 KEY BACKUP STORE
 * Sistema de backup persistente de chaves usando SQLite
 * Armazena backups de sessões e sender keys para recuperação em caso de acidente
 */

import * as fs from 'fs'
import * as path from 'path'

// Tipo para o banco de dados better-sqlite3
type Database = {
	prepare: (sql: string) => any
	exec: (sql: string) => void
	close: () => void
}

export class KeyBackupStore {
	private db: Database | null = null
	private initialized = false
	private dbPath: string

	constructor(sessionFolder?: string) {
		// Encontrar a pasta de dados baseado na pasta da sessão ou usar padrão
		if (sessionFolder) {
			this.dbPath = path.join(sessionFolder, 'chaves.db')
		} else {
			// Tentar encontrar a pasta dados/DB a partir do diretório raiz (configurável via DB_PATH)
			const dbFolder = process.env.DB_PATH || path.join('dados', 'DB')
			const possiblePaths: string[] = [
				path.join(process.cwd(), dbFolder, 'chaves.db'),
				path.join(process.cwd(), '..', dbFolder, 'chaves.db'),
				path.join(__dirname, '..', '..', '..', '..', dbFolder, 'chaves.db'),
			]
			
			// Usar o primeiro caminho onde a pasta pai existe
			this.dbPath = possiblePaths[0]!
			for (const p of possiblePaths) {
				const dir = path.dirname(p)
				if (fs.existsSync(dir)) {
					this.dbPath = p
					break
				}
			}
		}
	}

	/**
	 * Inicializa o banco de dados de backup
	 */
	async init(): Promise<boolean> {
		if (this.initialized) return true

		try {
			// Garantir que o diretório existe
			const dir = path.dirname(this.dbPath)
			if (!fs.existsSync(dir)) {
				fs.mkdirSync(dir, { recursive: true })
			}

			// Importar better-sqlite3 dinamicamente (compatível com ESM)
			// @ts-ignore - better-sqlite3 não tem tipos
			const { default: Database } = await import('better-sqlite3')
			this.db = new Database(this.dbPath)

			// Criar tabelas se não existirem
			this.db!.exec(`
				CREATE TABLE IF NOT EXISTS session_backup (
					id TEXT PRIMARY KEY,
					data TEXT NOT NULL,
					created_at INTEGER DEFAULT (strftime('%s', 'now')),
					updated_at INTEGER DEFAULT (strftime('%s', 'now'))
				);

				CREATE TABLE IF NOT EXISTS sender_key_backup (
					id TEXT PRIMARY KEY,
					data TEXT NOT NULL,
					created_at INTEGER DEFAULT (strftime('%s', 'now')),
					updated_at INTEGER DEFAULT (strftime('%s', 'now'))
				);

				CREATE TABLE IF NOT EXISTS pending_messages (
					id TEXT PRIMARY KEY,
					group_jid TEXT NOT NULL,
					participant_jid TEXT NOT NULL,
					sender_key_id TEXT NOT NULL,
					raw_data TEXT NOT NULL,
					timestamp INTEGER NOT NULL,
					retry_count INTEGER DEFAULT 0,
					created_at INTEGER DEFAULT (strftime('%s', 'now'))
				);

				CREATE INDEX IF NOT EXISTS idx_session_updated ON session_backup(updated_at);
				CREATE INDEX IF NOT EXISTS idx_sender_key_updated ON sender_key_backup(updated_at);
				CREATE INDEX IF NOT EXISTS idx_pending_sender_key ON pending_messages(sender_key_id);
				CREATE INDEX IF NOT EXISTS idx_pending_timestamp ON pending_messages(timestamp);
			`)

			// Limpar backups antigos (mais de 7 dias)
			const sevenDaysAgo = Math.floor(Date.now() / 1000) - (7 * 24 * 60 * 60)
			this.db!.prepare('DELETE FROM session_backup WHERE updated_at < ?').run(sevenDaysAgo)
			this.db!.prepare('DELETE FROM sender_key_backup WHERE updated_at < ?').run(sevenDaysAgo)
			// Limpar mensagens pendentes antigas (mais de 1 hora)
			const oneHourAgo = Date.now() - (60 * 60 * 1000)
			this.db!.prepare('DELETE FROM pending_messages WHERE timestamp < ?').run(oneHourAgo)

			this.initialized = true
			// console.log(`🔐 [KEY-BACKUP] Banco de backup inicializado: ${this.dbPath}`)
			return true
		} catch (error) {
			console.warn(`⚠️ [KEY-BACKUP] Falha ao inicializar banco de backup:`, (error as Error).message)
			return false
		}
	}

	/**
	 * Salva backup de uma sessão
	 */
	async backupSession(sessionId: string, data: any): Promise<boolean> {
		if (!this.initialized || !this.db) {
			await this.init()
		}
		if (!this.db) return false

		try {
			const jsonData = JSON.stringify(data)
			const now = Math.floor(Date.now() / 1000)
			
			this.db.prepare(`
				INSERT INTO session_backup (id, data, updated_at) 
				VALUES (?, ?, ?)
				ON CONFLICT(id) DO UPDATE SET data = ?, updated_at = ?
			`).run(sessionId, jsonData, now, jsonData, now)
			
			return true
		} catch (error) {
			return false
		}
	}

	/**
	 * Recupera backup de uma sessão
	 */
	async getSessionBackup(sessionId: string): Promise<any | null> {
		if (!this.initialized || !this.db) {
			await this.init()
		}
		if (!this.db) return null

		try {
			const row = this.db.prepare('SELECT data FROM session_backup WHERE id = ?').get(sessionId) as { data: string } | undefined
			if (row?.data) {
				return JSON.parse(row.data)
			}
		} catch (error) {
			// Silently ignore
		}
		return null
	}

	/**
	 * Remove backup de uma sessão
	 */
	async deleteSessionBackup(sessionId: string): Promise<void> {
		if (!this.db) return
		try {
			this.db.prepare('DELETE FROM session_backup WHERE id = ?').run(sessionId)
		} catch (error) {
			// Silently ignore
		}
	}

	/**
	 * Salva backup de uma sender key
	 */
	async backupSenderKey(keyId: string, data: any): Promise<boolean> {
		if (!this.initialized || !this.db) {
			await this.init()
		}
		if (!this.db) return false

		try {
			const jsonData = JSON.stringify(data)
			const now = Math.floor(Date.now() / 1000)
			
			this.db.prepare(`
				INSERT INTO sender_key_backup (id, data, updated_at) 
				VALUES (?, ?, ?)
				ON CONFLICT(id) DO UPDATE SET data = ?, updated_at = ?
			`).run(keyId, jsonData, now, jsonData, now)
			
			return true
		} catch (error) {
			return false
		}
	}

	/**
	 * Recupera backup de uma sender key
	 */
	async getSenderKeyBackup(keyId: string): Promise<any | null> {
		if (!this.initialized || !this.db) {
			await this.init()
		}
		if (!this.db) return null

		try {
			const row = this.db.prepare('SELECT data FROM sender_key_backup WHERE id = ?').get(keyId) as { data: string } | undefined
			if (row?.data) {
				return JSON.parse(row.data)
			}
		} catch (error) {
			// Silently ignore
		}
		return null
	}

	/**
	 * Remove backup de uma sender key
	 */
	async deleteSenderKeyBackup(keyId: string): Promise<void> {
		if (!this.db) return
		try {
			this.db.prepare('DELETE FROM sender_key_backup WHERE id = ?').run(keyId)
		} catch (error) {
			// Silently ignore
		}
	}

	/**
	 * Retorna estatísticas do backup
	 */
	getStats(): { sessions: number; senderKeys: number; pendingMessages: number; dbPath: string } {
		if (!this.db) {
			return { sessions: 0, senderKeys: 0, pendingMessages: 0, dbPath: this.dbPath }
		}

		try {
			const sessions = (this.db.prepare('SELECT COUNT(*) as count FROM session_backup').get() as { count: number })?.count || 0
			const senderKeys = (this.db.prepare('SELECT COUNT(*) as count FROM sender_key_backup').get() as { count: number })?.count || 0
			const pendingMessages = (this.db.prepare('SELECT COUNT(*) as count FROM pending_messages').get() as { count: number })?.count || 0
			return { sessions, senderKeys, pendingMessages, dbPath: this.dbPath }
		} catch (error) {
			return { sessions: 0, senderKeys: 0, pendingMessages: 0, dbPath: this.dbPath }
		}
	}

	// ===============================================
	// 🔐 PENDING MESSAGE QUEUE METHODS
	// ===============================================

	/**
	 * Adiciona mensagem à fila de pendentes
	 */
	async addPendingMessage(pending: {
		id: string
		groupJid: string
		participantJid: string
		senderKeyId: string
		rawData: string
		timestamp: number
		retryCount: number
	}): Promise<boolean> {
		if (!this.initialized || !this.db) {
			await this.init()
		}
		if (!this.db) return false

		try {
			this.db.prepare(`
				INSERT INTO pending_messages (id, group_jid, participant_jid, sender_key_id, raw_data, timestamp, retry_count)
				VALUES (?, ?, ?, ?, ?, ?, ?)
				ON CONFLICT(id) DO UPDATE SET retry_count = retry_count + 1
			`).run(
				pending.id,
				pending.groupJid,
				pending.participantJid,
				pending.senderKeyId,
				pending.rawData,
				pending.timestamp,
				pending.retryCount
			)
			console.log(`📥 [PENDING-QUEUE] Message ${pending.id} added to queue`)
			return true
		} catch (error) {
			console.warn('[PENDING-QUEUE] Failed to add message:', error)
			return false
		}
	}

	/**
	 * Obtém mensagens pendentes para um sender key específico
	 */
	async getPendingMessages(senderKeyId: string): Promise<Array<{
		id: string
		groupJid: string
		participantJid: string
		senderKeyId: string
		rawData: string
		timestamp: number
		retryCount: number
	}>> {
		if (!this.initialized || !this.db) {
			await this.init()
		}
		if (!this.db) return []

		try {
			const rows = this.db.prepare(`
				SELECT id, group_jid, participant_jid, sender_key_id, raw_data, timestamp, retry_count
				FROM pending_messages
				WHERE sender_key_id = ?
				ORDER BY timestamp ASC
			`).all(senderKeyId) as any[]

			return rows.map(row => ({
				id: row.id,
				groupJid: row.group_jid,
				participantJid: row.participant_jid,
				senderKeyId: row.sender_key_id,
				rawData: row.raw_data,
				timestamp: row.timestamp,
				retryCount: row.retry_count
			}))
		} catch (error) {
			console.warn('[PENDING-QUEUE] Failed to get pending messages:', error)
			return []
		}
	}

	/**
	 * Remove mensagem da fila
	 */
	async removePendingMessage(messageId: string): Promise<void> {
		if (!this.db) return
		try {
			this.db.prepare('DELETE FROM pending_messages WHERE id = ?').run(messageId)
		} catch (error) {
			// Silently ignore
		}
	}

	/**
	 * Limpa mensagens antigas da fila
	 */
	async cleanupOldPendingMessages(maxAgeMs: number): Promise<number> {
		if (!this.db) return 0
		try {
			const cutoff = Date.now() - maxAgeMs
			const result = this.db.prepare('DELETE FROM pending_messages WHERE timestamp < ?').run(cutoff)
			return result.changes || 0
		} catch (error) {
			return 0
		}
	}

	/**
	 * Obtém estatísticas da fila de pendentes
	 */
	async getPendingQueueStats(): Promise<{ total: number; byGroup: Record<string, number> }> {
		if (!this.db) return { total: 0, byGroup: {} }
		try {
			const total = (this.db.prepare('SELECT COUNT(*) as count FROM pending_messages').get() as { count: number })?.count || 0
			const groups = this.db.prepare('SELECT group_jid, COUNT(*) as count FROM pending_messages GROUP BY group_jid').all() as any[]
			const byGroup: Record<string, number> = {}
			for (const g of groups) {
				byGroup[g.group_jid] = g.count
			}
			return { total, byGroup }
		} catch (error) {
			return { total: 0, byGroup: {} }
		}
	}

	/**
	 * Fecha a conexão com o banco
	 */
	close(): void {
		if (this.db) {
			try {
				this.db.close()
			} catch (error) {
				// Silently ignore
			}
			this.db = null
			this.initialized = false
		}
	}
}

// Instância global do backup store (será inicializada quando necessário)
let globalBackupStore: KeyBackupStore | null = null

export function getKeyBackupStore(sessionFolder?: string): KeyBackupStore {
	if (!globalBackupStore) {
		globalBackupStore = new KeyBackupStore(sessionFolder)
	}
	return globalBackupStore
}
